public class UserInputProcessor {
    public List<Integer> parseUserAges(List<String> inputs) {
        var ages = new ArrayList<Integer>();

        for (String input : inputs) {
            if (input != null && !input.isBlank()) {
                try {
                    // Autoboxing: parseInt returns int, automatically wrapped to Integer
                    ages.add(Integer.parseInt(input.trim()));
                } catch (NumberFormatException e) {
                    System.err.println("Invalid age: " + input);
                }
            }
        }
        return ages;
    }

    public Optional<Double> calculateAverageAge(List<Integer> ages) {
        if (ages.isEmpty()) return Optional.empty();

        // Unboxing: Integer objects automatically converted to int for sum
        int sum = 0;
        for (Integer age : ages) {
            sum += age;  // age unboxed here
        }
        return Optional.of((double) sum / ages.size());
    }
}

public class DataAnalyzer {
    public record MinMaxResult(int min, int max) {}

    public MinMaxResult findMinMax(List<Integer> numbers) {
        if (numbers.isEmpty()) {
            throw new IllegalArgumentException("Cannot find min/max of empty list");
        }

        // Initialize to opposite extremes so first value always wins
        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;

        for (int num : numbers) {
            if (num < min) min = num;
            if (num > max) max = num;
        }
        return new MinMaxResult(min, max);
    }

    public Optional<Integer> safeAdd(int a, int b) {
        // Detect overflow before it happens
        if (a > 0 && b > Integer.MAX_VALUE - a) {
            return Optional.empty();  // Would overflow
        }
        if (a < 0 && b < Integer.MIN_VALUE - a) {
            return Optional.empty();  // Would underflow
        }
        return Optional.of(a + b);
    }
}

public class InputValidator {
    public boolean isValidUsername(String username) {
        if (username == null || username.length() < 3) return false;

        for (char c : username.toCharArray()) {
            // Unicode-aware: handles international letters correctly
            if (!Character.isLetterOrDigit(c) && c != '_') {
                return false;
            }
        }
        return true;
    }

    public int countDigits(String input) {
        int count = 0;
        for (char c : input.toCharArray()) {
            if (Character.isDigit(c)) count++;
        }
        return count;
    }

    public String toTitleCase(String text) {
        var result = new StringBuilder();
        boolean capitalizeNext = true;

        for (char c : text.toCharArray()) {
            if (Character.isWhitespace(c)) {
                capitalizeNext = true;
                result.append(c);
            } else if (capitalizeNext) {
                result.append(Character.toUpperCase(c));
                capitalizeNext = false;
            } else {
                result.append(Character.toLowerCase(c));
            }
        }
        return result.toString();
    }
}

import java.math.BigDecimal;

public class NumberProcessor {
    // Accepts any Number subclass: Integer, Double, BigDecimal, etc.
    public double calculatePercentage(Number value, Number total) {
        if (total.doubleValue() == 0) {
            throw new IllegalArgumentException("Total cannot be zero");
        }
        return (value.doubleValue() / total.doubleValue()) * 100;
    }

    public record Statistics(double sum, double average, int count) {}

    public Statistics analyze(List<? extends Number> numbers) {
        if (numbers.isEmpty()) {
            return new Statistics(0, 0, 0);
        }

        double sum = 0;
        for (Number num : numbers) {
            sum += num.doubleValue();  // Works for any Number subclass
        }

        return new Statistics(sum, sum / numbers.size(), numbers.size());
    }

    public boolean isWithinRange(Number value, Number min, Number max) {
        double v = value.doubleValue();
        return v >= min.doubleValue() && v <= max.doubleValue();
    }
}

public class ParseIntVsValueOf {
    public static void main(String[] args) {
        // parseInt returns a primitive int
        int i = Integer.parseInt("42");        // 42 (int)

        // valueOf returns an Integer object (uses the -128..127 cache)
        Integer obj = Integer.valueOf("42");   // Integer

        System.out.println(i + 1);             // 43
        System.out.println(obj.equals(42));    // true

        // Cache effect: valueOf reuses cached objects, parseInt has none
        Integer a = Integer.valueOf(100);
        Integer b = Integer.valueOf(100);
        System.out.println(a == b);            // true (cached)

        // Both throw NumberFormatException on bad input:
        // Integer.parseInt("abc");
    }
}
